69: /**
70:  * Builds the log context of a failed API request. Only the method and the matched route
71:  * pattern are used - never the query string or the concrete path, whose parameters may carry
72:  * credentials, email addresses or one-time UUIDs.
73:  * @param res response whose request is described
74:  * @returns the request context, or an empty string if the request is unavailable
75:  */
76: function getStatusContext(res: Response): string {
77:   const route = res.req?.route?.path;
78:   return res.req ? ` for ${res.req.method}${route ? ` ${route}` : ''}` : '';
79: }
80: 
81: /**
82:  * Sends a status response and logs error statuses with a level beforehand, so no API failure
83:  * degrades silently: 4xx are logged as `warn` (recoverable, e.g. invalid client requests) and
84:  * 5xx as `error` (server-side failures that need attention). Only the method and the matched
85:  * route pattern are logged - never the query string or the concrete path, whose parameters
86:  * may carry credentials, email addresses or one-time UUIDs.
87:  * @param res response to send the status to
88:  * @param status HTTP status code
89:  * @param message optional response message, defaults to the status text
90:  */
91: function sendStatus(res: Response, status: number, message?: string) {
92:   if (status >= 400) {
93:     const messageText = `API request${getStatusContext(res)} failed with status ${status}`;
94:     if (status >= 500) logger.error(messageText);
95:     else logger.warn(messageText);
96:   }
97:   const r: GenericResponse = {
98:     status: status
99:   };
100:   if (message) {
101:     r.message = message;
102:   } else {
103:     switch (status) {
104:       case 200:
105:         r.message = 'OK';
106:         break;
107:       case 201:
108:         r.message = 'Created';
109:         break;
110:       case 202:
111:         r.message = 'Accepted';
112:         break;
113:       case 204:
114:         r.message = 'No Content';
115:         break;
