487: export function getDailiesResponse(daily: DBDaily): DailyGetResponse {
488:   const dailiesOfDay = getDailiesOfDay();
489:   const typedPayload: DailyGetResponse = {} as DailyGetResponse;
490:   DAILY_DEFINITIONS.forEach(dailyDef => {
491:     const dailyValue = daily[dailyDef.dbColumn];
492:     typedPayload[dailyDef.dbColumn as keyof DailyGetResponse] = dailiesOfDay.includes(dailyDef.type)
493:       ? dailyValue
494:       : null;
495:   });
496:   return typedPayload;
497: }
