520:   return DBConnection.instance.transaction(async () => {
521:     const items = await DBItemsDAO.getByUserId(userId);
522:     const item = items.find(i => i.itemId == itemId);
523:     if (!item) return Promise.reject(APIRejectReason.NotFound);
524:     if (item.type == ItemType.Booster) {
525:       const cards = CardCollection.generateBoosterContent(Number(item.content)).map(c => c.id);
526:       if ((await DBItemsDAO.delete(itemId)) == 0) return Promise.reject(APIRejectReason.NotFound);
527:       for (const cardId of cards) {
528:         await DBDecksDAO.create(cardId, userId, false, true);
529:       }
530:       return {
531:         itemId: item.itemId,
532:         message: item.message,
533:         sol: [],
534:         cards: cards,
535:         boosters: []
536:       };
537:     } else if (item.type == ItemType.Box) {
538:       const content = <DBItemBoxContent[]>JSON.parse(item.content);
539:       if ((await DBItemsDAO.delete(itemId)) == 0) return Promise.reject(APIRejectReason.NotFound);
540:       for (const entry of content) {
541:         switch (entry.type) {
542:           case ItemBoxContentType.Booster:
543:             await DBItemsDAO.createBooster(userId, entry.value);
544:             break;
545:           case ItemBoxContentType.Card:
546:             await DBDecksDAO.create(entry.value, userId);
547:             break;
548:           case ItemBoxContentType.Sol:
549:             await DBProfilesDAO.increaseSol(userId, entry.value);
550:         }
551:       }
552:       return {
553:         itemId: item.itemId,
554:         message: item.message,
555:         sol: content.filter(c => c.type == ItemBoxContentType.Sol).map(c => c.value),
556:         cards: content.filter(c => c.type == ItemBoxContentType.Card).map(c => c.value),
557:         boosters: content.filter(c => c.type == ItemBoxContentType.Booster).map(c => c.value)
558:       };
559:     } else {
560:       return Promise.reject(INVALID_ITEM_TYPE);
561:     }
562:   });
563: }
