565: /**
566:  * Buys a booster pack in a single database transaction: the sol decrease and the booster item
567:  * creation commit together or not at all. Rejects with `APIRejectReason.ConditionNotMet` if the
568:  * user cannot afford the booster and with `APIRejectReason.NotFound` if the user is unknown.
569:  * @param userId id of the buying user
570:  * @param boosterNo edition number of the booster to buy
571:  */
572: export async function buyBooster(userId: number, boosterNo: number): Promise<void> {
573:   return DBConnection.instance.transaction(async () => {
574:     await DBProfilesDAO.decreaseSol(userId, rules.boosterCosts[boosterNo]);
575:     await DBItemsDAO.createBooster(userId, boosterNo);
576:   });
577: }

